-- Nadie escribe sin permiso: cada tabla exige el permiso de la pantalla que la usa.
-- Leer sigue igual (solo los datos de tu empresa). El admin siempre puede (has_permission).
create or replace function public.has_any_permission(p_keys text[])
 returns boolean language sql stable security definer set search_path to 'public'
as $$ select exists (select 1 from unnest(p_keys) k where public.has_permission(k)) $$;
revoke all on function public.has_any_permission(text[]) from public, anon;
grant execute on function public.has_any_permission(text[]) to authenticated, service_role;

create policy "inventory_items_select_company" on public.inventory_items for select to authenticated using (company_id = public.get_my_company_id());
alter policy "inventory_items_company" on public.inventory_items using (company_id = public.get_my_company_id() and (public.has_any_permission(array['canManageInventory','canTransferInventory','canEditLogistics','canImportInventory','canControlSiteTools','canPerformInspections','canScanInventoryQR','canPrintInventoryQR','canEditProjects','canManageProjectTeam']) or (select up.role from public.user_profiles up where up.id = auth.uid()) in ('supervisor','projectManager','logistic'))) with check (company_id = public.get_my_company_id() and (public.has_any_permission(array['canManageInventory','canTransferInventory','canEditLogistics','canImportInventory','canControlSiteTools','canPerformInspections','canScanInventoryQR','canPrintInventoryQR','canEditProjects','canManageProjectTeam']) or (select up.role from public.user_profiles up where up.id = auth.uid()) in ('supervisor','projectManager','logistic')));
